"""Shared editorial identity and contextual commercial placements."""
import html,re

def esc(s):return html.escape(str(s),quote=True)
def topic(a):
    text=(a['title']+' '+a['category']+' '+a['summary']).lower()
    for pattern,slug,label in [(r'ciment|cimenterie','ciments','ciment'),(r'acier|fer à béton|sonasid|sidérurg','fer-a-beton','fer à béton'),(r'panneau|cloison','panneaux-muraux','panneaux muraux'),(r'brique|agglo','agglos','agglos et briques'),(r'granulat|agrégat|sable|gravier','agregats','sable et granulats'),(r'coffrage|madrier','madriers','bois de coffrage')]:
        if re.search(pattern,text):return slug,label
    return '', 'matériaux de construction'
def masthead():
    return '<div class="zi-masthead" translate="no"><img src="/assets/zone-industrielle-logo.webp" width="92" height="92" alt="Logo Zone Industrielle"><div><span class="zi-kicker">LE JOURNAL · MAROC</span><h1>ZONE<br>INDUSTRIELLE</h1><p>Matériaux · Chantiers · Industrie</p></div></div><p class="zi-publisher">Décrypter les marchés. Suivre les chantiers. Comprendre l’industrie.</p>'
def offer(a,stage):
    slug,label=topic(a);url='/?'+('produit='+slug+'&' if slug else '')+'source=zone-industrielle#catalogue'
    return '<aside class="zi-offer" data-zi-offer data-product="'+esc(slug or 'materiaux')+'" data-label="'+esc(label)+'" data-stage="'+stage+'" aria-label="Proposition commerciale"><span class="zi-kicker">FOURNITURE · BANANA MATÉRIAUX</span><h2 data-offer-title>Vous recherchez '+esc(label)+' pour votre chantier ?</h2><p data-offer-copy>Précisez votre quantité et votre destination. Nous étudions le tarif, la disponibilité et la livraison.</p><div class="actions"><a class="btn" data-offer-click href="'+url+'">Préparer ma demande →</a><button class="btn outline" type="button" data-continue>Continuer la lecture</button></div><small>Proposition commerciale · Tarif et disponibilité à confirmer.</small></aside>'
def community(a):
    return '<section class="zi-community" data-article="'+esc(a['slug'])+'" aria-labelledby="zi-discussion"><h2 id="zi-discussion">Votre regard sur le sujet</h2><div class="actions"><button class="btn outline" type="button" id="zi-like" aria-pressed="false">♡ J’aime <span id="zi-like-count">0</span></button><button class="btn outline" type="button" data-zi-account>Rejoindre le journal</button></div><p id="zi-community-status" role="status"></p><div id="zi-comments"></div><form id="zi-comment-form"><label for="zi-comment">Votre commentaire</label><textarea id="zi-comment" maxlength="1500" minlength="3" rows="4" required placeholder="Partagez votre expérience ou posez une question."></textarea><p class="hint">Connectez-vous pour participer à la discussion.</p><button class="btn" type="submit">Envoyer mon commentaire</button></form></section>'
def privacy():
    return '''<section class="section"><div class="wrap article-layout"><h1>Vos données et votre espace lecteur</h1><p>Zone Industrielle est édité par Banana Matériaux. Contact : +212 602 64 44 54.</p><h2>Vos commandes</h2><p>Lorsque vous confirmez une commande sur le site, Banana Matériaux enregistre votre nom ou entreprise, votre téléphone, le chantier ou la destination, les matériaux et quantités, ainsi que la date et les précisions que vous renseignez. Ces informations sont hébergées sur notre infrastructure Cloudflare pour traiter et suivre votre commande. Elles ne sont pas publiées dans le journal et ne nécessitent pas de compte lecteur.</p><p>La réception est confirmée uniquement après enregistrement, avec une référence. La disponibilité et la date restent à confirmer avec notre équipe. Si vous choisissez WhatsApp, votre message est transmis via ce service uniquement lorsque vous l’envoyez. Pour une demande d’accès, de correction ou de suppression concernant une commande, contactez-nous au numéro ci-dessus en indiquant sa référence. Supprimer votre compte lecteur ne supprime pas les informations d’une commande.</p><h2>Inscription</h2><p>Le pseudonyme et l’adresse email servent à votre compte et à vos contributions. Le mot de passe est conservé sous forme d’empreinte chiffrée à sens unique. Avec Google, seuls l’identifiant, le nom et l’email vérifié sont demandés. Nous ne demandons aucun accès à vos contacts, fichiers ou messages Google.</p><p>Entreprise, métier, ville, téléphone et centres d’intérêt sont facultatifs. Ils servent à mieux répondre à vos demandes professionnelles. Votre email, téléphone et entreprise ne sont jamais affichés dans les commentaires.</p><h2>Choix distincts</h2><p>L’inscription et les messages commerciaux restent facultatifs. Vous pouvez lire le journal sans compte.</p><p>Les mesures de navigation sont désactivées. La lecture reste libre.</p><h2>Contributions et conservation</h2><p>Vos commentaires publics affichent votre pseudonyme. Une modération automatique peut se tromper ; les cas incertains restent en attente. Les textes refusés sont supprimés. Le texte des commentaires est analysé sur notre infrastructure Cloudflare, notamment par son service Workers AI ; ne publiez pas de coordonnées privées. Pour contester une décision, écrivez au contact ci-dessus. Les données de compte restent jusqu’à suppression ; sessions 30 jours ; compteurs de protection au plus 48 heures ; statistiques agrégées 90 jours. Les messages commerciaux ne sont pas envoyés tant qu’un canal de diffusion n’est pas activé.</p><h2>Vos droits et réglages</h2><p>Dans votre espace lecteur, vous pouvez exporter vos informations et supprimer compte, commentaires et réactions. Pour corriger vos informations ou toute autre demande, appelez-nous au numéro indiqué.</p><button class="btn outline" type="button" data-zi-account>Mon espace lecteur</button> <button class="btn outline" type="button" id="zi-revoke">Retirer mon accord de mesure</button></div></section>'''
